import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function App() {
    var count = React.useState(12), floating = React.useState(true), message = React.useState('');
    function select(n) {
        count[1](n);
        message[1]('');
        if (!n)
            document.querySelector('.controls button').focus();
    }
    return <div className="dsbulkactionsbar-example">
    <style>{exampleStyles}</style>
    <div className={"demo-stack"}>
    <div className={'controls'}>
    <S.DsButton tone={'secondary'} onClick={function () { select(12); }}>
    {'Выбрать 12 строк'}
    </S.DsButton>
    <S.DsSwitch label={'Плавающий вид'} checked={floating[0]} onChange={function (e) { floating[1](e.target.checked); }}/>
    </div>
    <S.DsBulkActionsBar count={count[0]} total={148} noun={'объектов'} floating={floating[0]} style={{ flexWrap: 'wrap' }} onSelectAll={function (all) { select(all ? 148 : 0); }} onClear={function () { select(0); }} actions={[
            <S.DsButton key={'group'} size={'sm'} tone={'secondary'} icon={'label'} onClick={function () { message[1]('Пример: назначение группы для ' + count[0] + ' объектов запрошено.'); }}>
        {'В группу'}
        </S.DsButton>,
            <S.DsButton key={'export'} size={'sm'} tone={'secondary'} icon={'download'} onClick={function () { message[1]('Пример: экспорт ' + count[0] + ' объектов запрошен.'); }}>
        {'Экспорт'}
        </S.DsButton>
        ]}/>
    <p className={'status'} role={'status'}>
    {message[0] || (count[0] ? 'Выбрано строк: ' + count[0] + '.' : 'Строки не выбраны — панель скрыта.')}
    </p>
    </div>
    </div>;
}

const exampleStyles = ".dsbulkactionsbar-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsbulkactionsbar-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsbulkactionsbar-example p{margin:0}\n.dsbulkactionsbar-example .controls{display:flex;flex-wrap:wrap;gap:16px;align-items:center}\n.dsbulkactionsbar-example .status{font:var(--ds-type-caption);color:var(--ds-fg-muted);margin:0}";

export { App as Example };
